const cfg = $input.first().json;
let base = String(cfg.siteBaseUrl || '');
while (base.endsWith('/')) base = base.slice(0, -1);
if (!base.startsWith('http://') && !base.startsWith('https://')) throw new Error('Config: siteBaseUrl must start with http:// or https://');
const brand = cfg.brand || {};
const slug = String(brand.slug || '');
const c = cfg.campaign || {};
const t = $now.setZone('Europe/Bucharest');
const todayUtc = Date.UTC(t.year, t.month - 1, t.day);
const deadlineUtc = Date.UTC(t.year, Number(c.deadlineMonth) - 1, Number(c.deadlineDay));
const days = Math.round((deadlineUtc - todayUtc) / 86400000);
if (!(days >= 0)) return [];
const MONTHS = ['ianuarie', 'februarie', 'martie', 'aprilie', 'mai', 'iunie', 'iulie', 'august', 'septembrie', 'octombrie', 'noiembrie', 'decembrie'];
const left = days === 0 ? 'astazi este ultima zi' : days === 1 ? 'mai este o zi' : 'mai sunt ' + days + ' zile';
const topic = String(c.name) + ' ' + t.year + ': ' + left + ' pana la termenul limita din ' + Number(c.deadlineDay) + ' ' + MONTHS[Number(c.deadlineMonth) - 1];
const eventId = 'campaign-' + String(c.key) + '-' + t.toFormat('yyyy-MM-dd');
const api = base + '/api/automation/social/v1';
return [{
  json: {
    brand: slug,
    event_id: eventId,
    days_left: days,
    url: api + '/generation-requests',
    runsUrl: api + '/runs',
    body: {
      workflow: 'campaign-presets',
      event_id: eventId,
      brand: slug,
      input: {
        source: { type: 'topic', topic, hooks: Array.isArray(c.hooks) ? c.hooks : [] },
        research: c.research === true,
        kinds: ['social'],
        count: Number(brand.count) || 2,
        language: 'ro',
        templates: Array.isArray(brand.templates) && brand.templates.length > 0 ? brand.templates : ['dark', 'light', 'mint'],
        platforms: brand.platforms,
      },
    },
  },
}];

const sent = $('Build requests').all();
return $input.all().map((item, i) => {
  const req = sent[i].json;
  const r = item.json;
  const body = r.body && typeof r.body === 'object' ? r.body : {};
  let status = 'error';
  const details = { brand: req.brand, days_left: req.days_left };
  if (r.error !== undefined) {
    details.error = String(r.error.message || r.error).slice(0, 300);
  } else if (r.statusCode >= 200 && r.statusCode < 300) {
    status = body.created === false ? 'skipped' : 'ok';
    details.statusCode = r.statusCode;
    details.request_id = body.request_id;
    details.created = body.created;
  } else {
    details.statusCode = r.statusCode;
    details.response = JSON.stringify(r.body === undefined ? null : r.body).slice(0, 300);
  }
  return { json: { url: req.runsUrl, body: { workflow: 'campaign-presets', event_id: req.event_id, status, details } } };
});
